import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"Creating and changing fields","description":"Create fields in a Grid, rename them, change their type, and delete them.","frontmatter":{"title":"Creating and changing fields","description":"Create fields in a Grid, rename them, change their type, and delete them."},"headers":[],"relativePath":"en/grids/felder.md","filePath":"en/grids/felder.md","lastUpdated":1787319236000}'),r={name:"en/grids/felder.md"};function o(s,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="creating-and-changing-fields" tabindex="-1">Creating and changing fields <a class="header-anchor" href="#creating-and-changing-fields" aria-label="Permalink to &quot;Creating and changing fields&quot;">​</a></h1><p>A <strong>field</strong> is a column of a Grid. Unlike a filter or sort order, fields apply to the <strong>entire Grid</strong> — changes take effect in every view, form, and flow.</p><h2 id="create-a-field" tabindex="-1">Create a field <a class="header-anchor" href="#create-a-field" aria-label="Permalink to &quot;Create a field&quot;">​</a></h2><ol><li>Click <strong>+</strong> at the right end of the column headers.</li><li>Give it a <strong>column name</strong>.</li><li>Choose the <strong>column type</strong>.</li><li>Configure the type if it has settings.</li></ol><p>The suggested name is <em>New field</em>.</p><p>→ <a href="/en/referenz/spaltentypen">Column type reference</a></p><h2 id="types-with-settings" tabindex="-1">Types with settings <a class="header-anchor" href="#types-with-settings" aria-label="Permalink to &quot;Types with settings&quot;">​</a></h2><p>Not every type is ready to use right away:</p><table tabindex="0"><thead><tr><th>Type</th><th>Setting</th></tr></thead><tbody><tr><td><strong>Single Select</strong>, <strong>Multiple Select</strong></td><td><em>Select settings</em> — option list, <em>Allow other options</em></td></tr><tr><td><strong>Currency</strong></td><td><em>Choose a currency</em>, plus decimal places</td></tr><tr><td><strong>Link record</strong>, <strong>Link multiple records</strong></td><td><em>Choose the view rows can be linked from</em></td></tr><tr><td><strong>Internal Link</strong></td><td><em>Choose one or more resource types (optional)</em></td></tr><tr><td><strong>Use linked value</strong>, <strong>Calculate sum</strong></td><td>Link field and target field</td></tr><tr><td><strong>Formula</strong></td><td>Expression and result type</td></tr></tbody></table><h3 id="select-options" tabindex="-1">Select options <a class="header-anchor" href="#select-options" aria-label="Permalink to &quot;Select options&quot;">​</a></h3><p>In the <em>Select settings</em> dialog, you create the options. Use <em>Find an option</em> to search longer lists.</p><p><strong>Allow other options</strong> additionally permits free text — in the form, this appears as <em>Other input</em>.</p><div class="tip custom-block"><p class="custom-block-title">Option order carries over</p><p>The order of options determines the column order in the <a href="/en/ansichten/kanban">Kanban board</a> and the order in the form. Set it deliberately — for example, along the process rather than alphabetically.</p></div><p>Error messages: <em>The option must not be empty</em>, <em>The option must not be a duplicate</em>.</p><h2 id="edit-a-field" tabindex="-1">Edit a field <a class="header-anchor" href="#edit-a-field" aria-label="Permalink to &quot;Edit a field&quot;">​</a></h2><p>Use the menu in the column header:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Edit field</strong></td><td>Opens column name and column type</td></tr><tr><td><strong>Edit column description</strong></td><td>Explanatory text for the field</td></tr><tr><td><strong>Manage field key</strong></td><td>Technical identifier</td></tr></tbody></table><h3 id="renaming" tabindex="-1">Renaming <a class="header-anchor" href="#renaming" aria-label="Permalink to &quot;Renaming&quot;">​</a></h3><p>Uncritical: views, forms, and flows don&#39;t reference fields internally by name, and keep working.</p><p>Error message on duplicates: <em>The name already exists</em>. For names that are too long: <em>The name can be at most {max} characters long.</em></p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>The column description also appears in <a href="/en/formulare/felder-konfigurieren">forms</a> as help text beneath the field.</p><div class="tip custom-block"><p class="custom-block-title">One sentence saves a lot of follow-up questions</p><p>Especially for fields other people fill in, a short explanation noticeably cuts down mistakes — &quot;Please include the country code, e.g. +49…&quot;.</p></div><h3 id="field-key" tabindex="-1">Field key <a class="header-anchor" href="#field-key" aria-label="Permalink to &quot;Field key&quot;">​</a></h3><p>A <strong>key</strong> is an additional, readable identifier for a field — independent of its name. The interface describes it as a <em>readable identifier of a column</em>, used <em>to connect a Grid with an app</em>.</p><p>You need it wherever something outside the Grid must address a specific field without relying on its name: in the API, in form values — and in <a href="/en/apptiveteams/team-space">ApptiveTeams</a>, where the app finds its entire configuration via keys.</p><p>You can assign all keys of a Grid at once via <strong>Manage field keys</strong> in the view&#39;s menu (⋮).</p><div class="tip custom-block"><p class="custom-block-title">Names are for people, keys are for systems</p><p>Because name and key are separate, you can rename a column anytime without breaking a connected app or interface. So assign keys deliberately, and don&#39;t change them afterward.</p></div><h3 id="changing-the-type" tabindex="-1">Changing the type <a class="header-anchor" href="#changing-the-type" aria-label="Permalink to &quot;Changing the type&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Changing the type can lose values</p><p>ApptiveGrid tries to carry over existing values. If a value doesn&#39;t fit the new type, it&#39;s lost — without asking row by row.</p><p>For populated columns, take a <a href="/en/grids/csv-export">CSV export</a> as a backup first.</p></div><p>Typical cases:</p><table tabindex="0"><thead><tr><th>Change</th><th>Result</th></tr></thead><tbody><tr><td>Text → Number</td><td>Non-numeric values are lost</td></tr><tr><td>Text → Single Select</td><td>Values without a matching option are lost</td></tr><tr><td>Number → Text</td><td>Uncritical</td></tr><tr><td>Date → Text</td><td>Uncritical, but date filters are dropped</td></tr><tr><td>Anything → Link</td><td>Values are generally lost</td></tr></tbody></table><p>If a filter blocks the change, ApptiveGrid reports:</p><blockquote><p><em>Change not possible. This field is used in a filter.</em></p></blockquote><p>Remove the filter — it can be in <strong>any</strong> view of the Grid, not just the one you have open.</p><h2 id="field-key-1" tabindex="-1">Field key <a class="header-anchor" href="#field-key-1" aria-label="Permalink to &quot;Field key&quot;">​</a></h2><p>The <strong>field key</strong> is the technical identifier of a field. It matters when you access the Grid via the <a href="/en/integrationen/api-zugangsdaten">API</a>.</p><p>You don&#39;t need it for working in the interface.</p><h2 id="delete-a-field" tabindex="-1">Delete a field <a class="header-anchor" href="#delete-a-field" aria-label="Permalink to &quot;Delete a field&quot;">​</a></h2><p>Via the column menu, with confirmation.</p><div class="danger custom-block"><p class="custom-block-title">Deleting removes the values from all entries</p><p>This can&#39;t be undone. Check beforehand whether the field is used:</p><ul><li>in a view&#39;s <strong>filters, sorts, groupings</strong></li><li>in <strong>forms</strong></li><li>in <strong>flows</strong> — as a trigger condition or in an action</li><li>in <strong>calculated fields</strong> — as the target field of a lookup or sum</li><li>in <strong>pages</strong> — as an input field or in conditional visibility</li></ul></div><h2 id="hide-a-field-instead-of-deleting-it" tabindex="-1">Hide a field instead of deleting it <a class="header-anchor" href="#hide-a-field-instead-of-deleting-it" aria-label="Permalink to &quot;Hide a field instead of deleting it&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">The safer alternative</p><p>If a field is no longer needed but the old values should be kept, hide it in every view instead of deleting it. The data stays available, and the table still stays tidy.</p><p>→ <a href="/en/ansichten/spalten-verwalten">Manage columns</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/referenz/spaltentypen">Column type reference</a></li><li><a href="/en/grids/verknuepfungen">Link Grids</a></li><li><a href="/en/grids/berechnete-felder">Calculated Fields</a></li></ul>',45)])])}const g=t(r,[["render",o]]);export{f as __pageData,g as default};
